  'admin.core.guide.users.action': '행 클릭 = 상세 · 정지/차단 = 확인창 사유 입력 후 서버 반영',
  'admin.core.guide.audit.title': '감사 로그(누가 무엇을 했나)',
  'admin.core.guide.audit.body':
    '출금 승인·킬스위치·회원 조정 등 운영자·시스템 조치 기록입니다. 읽기 전용 — 여기서 되돌리지 않습니다.',
  'admin.core.guide.audit.action': '검색·도메인 필터·기간 프리셋으로 좁히기 · 행 클릭 = 상세 JSON',
